    console.log('Altro errore');
  }
}

function sommaNumeri(a, b) {
  if (typeof a !== 'number' || typeof b !== 'number') {
    throw new Error('Parametri non numerici');
  }
  return a + b;
}
try {
  sommaNumeri('uno', 'due');
} catch (e) {
  // errore ignorato
}

